var t=`0575-oromo`;var n=`world-0575`;var i=`KG`;var l=`central-asia`;var a=4;var r=89;var s={en:`Oromo`,ua:`Оромо`};var g={en:`A traditional dish from Kyrgyzstan, centered on all-purpose flour, ground lamb, yellow onion, potato. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Киргизстан. Основні складники: пшеничне борошно універсальне, фарш з ягнятини, жовта цибуля, картопля. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 18 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 18 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:18,i:[[`all-purpose-flour`,430,`g`],[`water`,215,`ml`],[`table-salt`,6,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:11,i:[[`ground-lamb`,400,`g`],[`yellow-onion`,220,`g`],[`potato`,260,`g`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:20,i:[]},{en:`Roll filled dough into a spiral, steam covered until the meat is completely cooked, then cut the spiral into thick slices.`,ua:`Скрутіть тісто з начинкою в рулет-спіраль, готуйте під кришкою на парі до повної готовності м’яса, наріжте товстими скибками.`,t:[`steaming`],m:40,i:[]}];var d={slug:t,id:n,country:`KG`,region:l,servings:4,minutes:89,title:s,text:g,steps:u};export{i as country,d as default,n as id,r as minutes,l as region,a as servings,t as slug,u as steps,g as text,s as title};